        return switch (forma) {
            case PIX, BOLETO -> parcelas == 1;
            case CARTAO -> parcelas >= 1 && parcelas <= 12;
        };
    }

    private BigDecimal arredondar(BigDecimal valor) {
        return valor.setScale(ESCALA_MOEDA, ARREDONDAMENTO);
    }
}

