private BigDecimal calcularJurosCartao(BigDecimal total, Integer parcelas) {
    if (parcelas <= 3) {
        return BigDecimal.ZERO;
    }

    BigDecimal taxa = new BigDecimal("0.0199");
    BigDecimal numerador = total.multiply(taxa);
    BigDecimal denominator = BigDecimal.ONE.add(taxa).pow(parcelas);
    BigDecimal divisor = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(denominator, 10, ARREDONDAMENTO));

    BigDecimal parcela = numerador.divide(divisor, ESCALA_MOEDA, ARREDONDAMENTO);
    BigDecimal totalComJuros = parcela.multiply(new BigDecimal(parcelas));
    return totalComJuros.subtract(total);
}

