private BigDecimal calcularJurosCartao(BigDecimal total, Integer parcelas) {
    if (parcelas <= 3) {
        return BigDecimal.ZERO;
    }

    BigDecimal taxa = new BigDecimal("0.0199");
    BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxa);
    BigDecimal potencia = umMaisTaxa.pow(parcelas);
    BigDecimal numerador = total.multiply(taxa).multiply(potencia);
    BigDecimal denominador = potencia.subtract(BigDecimal.ONE);

    BigDecimal parcela = numerador.divide(denominador, ESCALA_MOEDA, ARREDONDAMENTO);
    BigDecimal totalComJuros = parcela.multiply(new BigDecimal(parcelas));
    return totalComJuros.subtract(total);
}

